CREATE DATABASE IF NOT EXISTS `turkmenistan_geo`
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE `turkmenistan_geo`;

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS region_types (
  type varchar(32) PRIMARY KEY,
  description varchar(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE description=VALUES(description);

CREATE TABLE IF NOT EXISTS regions (
  id bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,
  parent_id bigint unsigned NULL,
  slug varchar(255) NOT NULL UNIQUE,
  name_tm varchar(255) NOT NULL, name_en varchar(255) NOT NULL, name_ru varchar(255),
  type varchar(32) NOT NULL, latitude decimal(9,6), longitude decimal(9,6),
  country_code char(2) NOT NULL DEFAULT 'TM',
  verification_status varchar(32) NOT NULL DEFAULT 'verified',
  source_url text, source_date date,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_regions_parent FOREIGN KEY(parent_id) REFERENCES regions(id),
  CONSTRAINT fk_regions_type FOREIGN KEY(type) REFERENCES region_types(type),
  CONSTRAINT chk_regions_lat CHECK(latitude BETWEEN -90 AND 90),
  CONSTRAINT chk_regions_lon CHECK(longitude BETWEEN -180 AND 180)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS region_aliases (
  id bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,
  region_id bigint unsigned NOT NULL,
  alias varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  language varchar(8) NOT NULL,
  alias_type varchar(32) NOT NULL, normalized_alias varchar(255) NOT NULL,
  created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_region_alias(region_id,alias),
  CONSTRAINT fk_alias_region FOREIGN KEY(region_id) REFERENCES regions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Preserve distinct display aliases such as Daşoguz, Dashoguz, and dasoguz.
ALTER TABLE region_aliases
  MODIFY alias varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL;

CREATE OR REPLACE VIEW region_search AS
SELECT r.id,r.parent_id,r.slug,r.name_tm canonical_name,r.type,
       a.alias,a.language,a.alias_type,a.normalized_alias
FROM regions r JOIN region_aliases a ON a.region_id=r.id;

DROP PROCEDURE IF EXISTS find_region;
DELIMITER $$
CREATE PROCEDURE find_region(IN query_text varchar(255))
BEGIN
  IF EXISTS(SELECT 1 FROM region_search WHERE alias=query_text OR normalized_alias=LOWER(query_text)) THEN
    SELECT id,parent_id,slug,canonical_name,type,alias,language,alias_type
    FROM region_search
    WHERE alias=query_text OR normalized_alias=LOWER(query_text)
    ORDER BY (alias=query_text) DESC,canonical_name;
  ELSE
    SELECT id,parent_id,slug,canonical_name,type,alias,language,alias_type
    FROM region_search
    WHERE normalized_alias LIKE CONCAT('%',LOWER(query_text),'%')
    ORDER BY canonical_name
    LIMIT 50;
  END IF;
END$$
DELIMITER ;

SET @index_sql := IF(
  EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='regions' AND index_name='idx_regions_parent'),
  'SELECT 1', 'CREATE INDEX idx_regions_parent ON regions(parent_id)');
PREPARE index_stmt FROM @index_sql; EXECUTE index_stmt; DEALLOCATE PREPARE index_stmt;

SET @index_sql := IF(
  EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='regions' AND index_name='idx_regions_type'),
  'SELECT 1', 'CREATE INDEX idx_regions_type ON regions(type)');
PREPARE index_stmt FROM @index_sql; EXECUTE index_stmt; DEALLOCATE PREPARE index_stmt;

SET @index_sql := IF(
  EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='region_aliases' AND index_name='idx_alias_normalized'),
  'SELECT 1', 'CREATE INDEX idx_alias_normalized ON region_aliases(normalized_alias)');
PREPARE index_stmt FROM @index_sql; EXECUTE index_stmt; DEALLOCATE PREPARE index_stmt;


